import {properties,state,money,neighborhoods} from './data.js';
import {logo,icon,photo,button,regionOptions,escapeHTML} from './ui.js';
export const adminNav=[['dashboard','home','Dashboard'],['imoveis','building','Imóveis'],['cadastro','plus','Cadastrar imóvel'],['clientes','user','Clientes e Matches'],['agendamentos','calendar','Agendamentos'],['documentos','file','Documentos'],['midia','image','Mídia e criativos'],['relatorios','chart','Relatórios'],['configuracoes','settings','Configurações']];
export function adminPage(section='dashboard'){return `<div class="admin-layout"><aside class="admin-sidebar">${logo()}<span class="admin-caption">PAINEL ADMINISTRATIVO</span><nav aria-label="Administração">${adminNav.map(([key,ic,title])=>`<a href="#/admin${key==='dashboard'?'':'/'+key}" class="${section===key?'selected':''}">${icon(ic)}${title}${key==='clientes'?'<i class="notification-dot"></i>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-art"><i></i><i></i><i></i></div><strong>Zona Leste, SP</strong><p>Penha · Vila Matilde · Tatuapé<br>Vila Formosa · Ponte Rasa · Vila Ré</p><a href="#/">${icon('back')}Voltar ao site</a></div></aside><main id="main" class="admin-main"><header class="admin-topbar"><div><span class="eyebrow">PROPERTY MATCH / ESPAÇO DO CORRETOR</span><h1>${section==='dashboard'?'Boa noite, Pedro.':adminNav.find(n=>n[0]===section)?.[2]||'Painel'}</h1><p>${section==='dashboard'?'Aqui está o resumo da sua imobiliária hoje.':'Organização para cuidar de cada oportunidade.'}</p></div><div class="admin-top-actions"><a href="#/admin/imoveis" class="admin-search">${icon('search')}Buscar imóvel ou código...<kbd>/</kbd></a><button class="round" data-action="notifications" aria-label="Notificações">${icon('bell')}<i class="notification-dot"></i></button><span class="avatar">PD</span></div></header><div class="admin-demo">${icon('info')}Ambiente demonstrativo · indicadores e registros fictícios · sem dados pessoais reais</div>${section==='dashboard'?dashboard():section==='imoveis'?`<section class="panel"><div class="section-heading"><h2>Seu portfólio</h2>${button('Cadastrar imóvel','#/admin/cadastro','dark','plus')}</div><form id="admin-filter" class="admin-filter"><input name="query" placeholder="Buscar por nome, bairro ou código" aria-label="Buscar imóvel"><select name="mode" aria-label="Modalidade"><option value="">Todas as modalidades</option><option>Alugar</option><option>Comprar</option></select><button class="btn dark">Filtrar${icon('search')}</button></form><div id="admin-table">${propertyTable(properties)}</div></section>`:section==='cadastro'?registration():section==='documentos'?documents():section==='agendamentos'?appointments():section==='clientes'?clients():section==='midia'?media():section==='relatorios'?reports():settings()}<div class="admin-footer"><span>Property Match · MVP visual</span><span>Dados de demonstração / 2026</span></div></main></div>`;}
function dashboard(){return `<div class="dashboard-grid"><div class="dashboard-main"><div class="metrics">${[['building','Imóveis no catálogo','7','5 para alugar'],['user','Matches nesta sessão',state.likes.length,'Seleção local'],['calendar','Visitas simuladas',state.appointments.length,'Neste navegador']].map(([ic,l,n,t])=>`<article class="metric"><span class="metric-icon">${icon(ic)}</span><div><h3>${l}</h3><strong>${n}</strong></div><span class="status green">${t}</span></article>`).join('')}</div><div class="charts-row"><section class="panel chart-panel"><div class="section-heading"><h2>Desempenho de locação</h2><div class="chart-legend"><span>● Interesse</span><span>● Visitas</span></div></div>${chart()}<p class="micro">Série ilustrativa · últimos 7 dias</p></section><section class="panel conversion"><h2>Taxa de conversão</h2><div class="donut"><span>32<small>%</small></span></div><span class="status green">↑ 6,8 p.p.</span><p class="micro">Indicador fictício</p></section></div></div><section class="panel pending"><div class="section-heading"><h2>${icon('check')}Pendências</h2><span class="count">5</span></div>${['Revisar apresentação do Neo Carrão','Atualizar avaliação territorial','Conferir galeria da Vila Matilde','Preparar ficha de locação','Revisar imóveis em destaque'].map(t=>`<label><input type="checkbox"><span>${t}</span>${icon('chevron')}</label>`).join('')}<p class="micro">Lista demonstrativa de organização diária.</p></section></div><section class="panel recent-properties"><div class="section-heading"><h2>Imóveis recentes</h2><div class="tabs"><button class="selected" data-admin-mode="">Todos (7)</button><button data-admin-mode="Alugar">Locação (5)</button><button data-admin-mode="Comprar">Venda (2)</button></div>${button('Cadastrar imóvel','#/admin/cadastro','dark','plus')}</div><div id="admin-table">${propertyTable(properties.slice(0,4))}</div></section>`;}
export function propertyTable(items){return `<div class="table-scroll"><table><thead><tr><th>Imóvel</th><th>Bairro</th><th>Finalidade</th><th>Valor</th><th>Ruído (região)</th><th>Status</th><th>Ações</th></tr></thead><tbody>${items.map(p=>`<tr><td><a class="table-property" href="#/imovel/${p.id}">${photo(p.photo)}<span><b>${p.id}</b><small>${p.beds} dorms. · ${p.area} m² · ${p.parking} vaga${p.parking!==1?'s':''}</small></span></a></td><td>${p.region}</td><td><span class="status neutral">${icon(p.mode==='Alugar'?'calendar':'home')}${p.mode==='Alugar'?'Locação':'Venda'}</span></td><td><b>${money(p.price)}</b></td><td><span class="status ${p.noise==='Baixo'?'green':p.noise==='Moderado'?'warm':'neutral'}">${icon('sound')}${p.noise}</span></td><td><span class="status ${p.status==='Publicado'?'published':'warm'}">${p.status==='Publicado'?'●':'◷'} ${p.status}</span></td><td><a href="#/imovel/${p.id}" aria-label="Ver ${p.id}">${icon('arrow')}</a></td></tr>`).join('')||'<tr><td colspan="7">Nenhum imóvel encontrado. Ajuste os filtros.</td></tr>'}</tbody></table></div>`;}
function chart(){return `<svg class="performance-chart" viewBox="0 0 650 160" role="img" aria-label="Gráfico ilustrativo: interesse e visitas crescem ao longo da semana"><defs><linearGradient id="areaGreen" x2="0" y2="1"><stop stop-color="#14543c" stop-opacity=".35"/><stop offset="1" stop-color="#14543c" stop-opacity=".02"/></linearGradient><linearGradient id="areaYellow" x2="0" y2="1"><stop stop-color="#e8b51e" stop-opacity=".4"/><stop offset="1" stop-color="#e8b51e" stop-opacity=".02"/></linearGradient></defs><g stroke="#d8d1c5" stroke-width="1"><path d="M35 30H635M35 65H635M35 100H635M35 130H635"/></g><path d="M35 105Q90 78 135 80T235 65T335 80T435 45T535 50T635 25V130H35Z" fill="url(#areaYellow)"/><path d="M35 105Q90 78 135 80T235 65T335 80T435 45T535 50T635 25" fill="none" stroke="#db9c06" stroke-width="2.5"/><path d="M35 120Q90 110 135 103T235 92T335 108T435 65T535 80T635 43V130H35Z" fill="url(#areaGreen)"/><path d="M35 120Q90 110 135 103T235 92T335 108T435 65T535 80T635 43" fill="none" stroke="#14543c" stroke-width="2.5"/><g font-size="12" fill="#68665e">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map((x,i)=>`<text x="${35+i*97}" y="153">${x}</text>`).join('')}</g></svg>`;}
export const registrationSteps=['Identificação','Endereço','Características','Comercial','Avaliação territorial','Fotografias e vídeos','Apresentação','Revisão'];
export let registrationStep=0;
export let draft={title:'',code:'',region:'',type:'Apartamento',mode:'Alugar',model:'Essencial'};
export function setRegistrationStep(n){registrationStep=Math.max(0,Math.min(7,n));}
export function registration(){return `<section class="registration"><div class="registration-steps">${registrationSteps.map((s,i)=>`<div class="${i===registrationStep?'active':i<registrationStep?'done':''}"><span>${i<registrationStep?icon('check'):String(i+1).padStart(2,'0')}</span><b>${s}</b></div>`).join('')}</div><div class="panel registration-panel"><div class="section-heading"><div><span class="eyebrow">ETAPA ${registrationStep+1} DE 8</span><h2>${registrationSteps[registrationStep]}</h2></div><span class="status neutral">Rascunho demonstrativo</span></div><form id="registration-form">${registrationFields()}<div class="wizard-actions">${registrationStep?`<button type="button" class="btn outline" data-wizard-back>${icon('back')}Voltar</button>`:'<a href="#/admin/imoveis">Cancelar</a>'}<button class="btn dark">${registrationStep===7?'Concluir demonstração':'Continuar'}${icon(registrationStep===7?'check':'arrow')}</button></div></form></div></section>`;}
const field=(label,name,type='text',required=true)=>`<label>${label}${required?' *':''}<input type="${type}" name="${name}" value="${escapeHTML(draft[name]||'')}" ${required?'required':''} ${type==='number'?'min="0"':''}></label>`;
function registrationFields(){switch(registrationStep){case 0:return `<p class="form-intro">Comece pelas informações que identificam o imóvel. Use apenas dados fictícios.</p><div class="form-grid">${field('Título do imóvel','title')}${field('Código de referência','code')}<label>Tipo de imóvel<select name="type">${['Apartamento','Casa','Studio'].map(x=>`<option ${draft.type===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('Responsável fictício','agent')}</div>`;case 1:return `<p class="form-intro">Localização demonstrativa. Não informe endereços ou dados de proprietários reais.</p><div class="form-grid"><label>Bairro *<select name="region" required><option value="">Selecione um bairro</option>${neighborhoods.map(n=>`<option ${draft.region===n?'selected':''}>${n}</option>`).join('')}</select></label>${field('Rua fictícia','street')}${field('Número fictício','number')}${field('Complemento','complement','text',false)}<label>Cidade<input value="São Paulo" readonly></label><label>Estado<input value="SP" readonly></label></div>`;case 2:return `<div class="form-grid">${field('Área útil (m²)','area','number')}${field('Dormitórios','beds','number')}${field('Banheiros','baths','number')}${field('Vagas','parking','number')}</div><label>Características e diferenciais<textarea name="features" rows="4">${escapeHTML(draft.features||'')}</textarea></label>`;case 3:return `<div class="form-grid"><label>Finalidade<select name="mode"><option ${draft.mode==='Alugar'?'selected':''}>Alugar</option><option ${draft.mode==='Comprar'?'selected':''}>Comprar</option></select></label>${field('Valor (R$)','price','number')}${field('Condomínio mensal (R$)','fee','number',false)}${field('IPTU mensal (R$)','tax','number',false)}</div>`;case 4:return `<p class="form-intro">Registre condições observáveis e a origem da informação. Não use características de pessoas ou comunidades como critérios territoriais.</p><div class="form-grid"><label>Ruído percebido<select name="noise">${['Não disponível','Baixo','Moderado','Alto'].map(x=>`<option ${draft.noise===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Origem da informação<select name="source">${['Não disponível','Observação direta (verificada)','Relato de terceiro (não verificado)'].map(x=>`<option ${draft.source===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('Período observado','period','text',false)}${field('Data da observação','date','date',false)}${field('Responsável fictício','observer','text',false)}${field('Mobilidade','mobility','text',false)}${field('Topografia','topography','text',false)}${field('Infraestrutura','infrastructure','text',false)}${field('Serviços próximos','services','text',false)}</div><p class="micro">Campos em branco serão apresentados como “Não disponível”.</p>`;case 5:return `<p class="form-intro">Escolha uma capa do acervo demonstrativo. Arquivos pessoais não são recebidos nem armazenados.</p><div class="media-picker">${['living','bedroom','dining','balcony'].map((k,i)=>`<label>${photo(k)}<span><input type="radio" name="cover" value="${k}" ${(draft.cover||'living')===k?'checked':''}>Fotografia ${i+1}</span></label>`).join('')}</div><div class="demo-ribbon">${icon('image')}Vídeo indisponível nesta demonstração. A apresentação utiliza fotografia.</div>`;case 6:return `<p class="form-intro">Duas maneiras de apresentar o mesmo imóvel, com os mesmos dados.</p><div class="model-picker">${['Essencial','Signature'].map(m=>`<label class="model-choice">${photo(m==='Essencial'?'living':'cinematic')}<div><input type="radio" name="model" value="${m}" ${draft.model===m?'checked':''}><h3>${m}</h3><p>${m==='Essencial'?'Informação clara, galeria e agendamento.':'Narrativa editorial, grandes imagens e ritmo cinematográfico.'}</p></div></label>`).join('')}</div>`;case 7:return `<div class="review-draft">${photo(draft.cover||'living')}<div><span class="eyebrow">${escapeHTML(draft.code)}</span><h2>${escapeHTML(draft.title)}</h2><p>${escapeHTML(draft.region)} · ${escapeHTML(draft.type)}</p><strong class="price">${money(draft.price||0)}</strong><p>${escapeHTML(draft.area)} m² · ${escapeHTML(draft.beds)} dormitórios · ${escapeHTML(draft.parking)} vagas</p><span class="status green">Apresentação ${escapeHTML(draft.model)}</span></div></div><div class="territorial-grid"><div><small>RUÍDO</small><b>${escapeHTML(draft.noise||'Não disponível')}</b></div><div><small>ORIGEM</small><b>${escapeHTML(draft.source||'Não disponível')}</b></div><div><small>RESPONSÁVEL</small><b>${escapeHTML(draft.observer||'Não disponível')}</b></div><div><small>OBSERVAÇÃO</small><b>${escapeHTML(draft.period||'Não disponível')} · ${escapeHTML(draft.date||'Sem data')}</b></div></div><p class="form-intro">Esta ação conclui o fluxo demonstrativo. O imóvel não será publicado nem incluído no catálogo.</p>`;}}
function documents(){return `<section class="documents-intro"><span class="eyebrow">CENTRAL DE DOCUMENTOS</span><h2>O próximo passo,<br>bem organizado.</h2><p>Modelos demonstrativos em PDF preenchível para conhecer o fluxo.<br>Não preencha com informações pessoais reais.</p></section><div class="document-grid">${[['locacao','Ficha de locação','Dados do interessado e informações da proposta.'],['proprietario','Ficha de proprietário','Identificação do imóvel e condições comerciais.'],['interessado','Ficha de interessado','Preferências e informações para atendimento.']].map(([key,t,d],i)=>`<article class="panel document-card"><span class="document-number">0${i+1}</span>${icon('file')}<span class="status neutral">PDF PREENCHÍVEL · DEMO</span><h3>${t}</h3><p>${d}</p><a class="btn dark full" href="./assets/ficha-${key}.pdf" download>${icon('download')}Baixar ficha</a></article>`).join('')}</div><section class="panel document-instructions"><h2>Como funciona</h2><div>${[['01','Baixe o modelo','Abra o PDF em um leitor com suporte a campos preenchíveis.'],['02','Explore o preenchimento','Use somente dados fictícios e salve uma cópia no seu dispositivo.'],['03','Envio pelo WhatsApp','Em uma operação real, confirme o contato do corretor e anexe o PDF na conversa. Este protótipo não recebe ou envia documentos.']].map(([n,t,d])=>`<article><span>${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><p class="privacy-note">${icon('info')}Nenhum documento pessoal é armazenado pela plataforma. Não há integração com WhatsApp.</p></section>`;}
function appointments(){return `<section class="panel"><div class="section-heading"><h2>Próximas visitas</h2>${button('Explorar imóveis','#/busca')}</div>${state.appointments.length?`<div class="appointments-list">${state.appointments.map((a,i)=>{const p=properties.find(x=>x.id===a.id);return `<article>${photo(p.photo)}<div><span class="eyebrow">${a.date.split('-').reverse().join('/')} · ${a.time}</span><h3>${p.name}</h3><p>${p.region} · ${p.id}</p></div><span class="status green">Simulada</span><button class="btn outline" data-cancel-appointment="${i}">Cancelar</button></article>`;}).join('')}</div>`:'<div class="empty"><h2>Sua agenda está livre.</h2><p>Agende uma visita demonstrativa na página de um imóvel.</p></div>'}</section>`;}
function clients(){return `<section class="panel"><div class="section-heading"><h2>Conexões da demonstração</h2><span class="status neutral">Sem dados pessoais</span></div><div class="metrics"><article class="metric"><div><h3>Imóveis curtidos</h3><strong>${state.likes.length}</strong></div>${icon('heart')}</article><article class="metric"><div><h3>Favoritos salvos</h3><strong>${state.favorites.length}</strong></div>${icon('save')}</article><article class="metric"><div><h3>Visitas simuladas</h3><strong>${state.appointments.length}</strong></div>${icon('calendar')}</article></div><h3 class="subheading">Preferências da sessão</h3><div class="preference-summary"><span>Região: <b>${state.preferences.region||'Toda a Zona Leste'}</b></span><span>Orçamento: <b>${money(state.preferences.max)}</b></span><span>Dormitórios: <b>${state.preferences.beds} ou mais</b></span></div>${propertyTable(properties.filter(p=>state.likes.includes(p.id)))}${button('Abrir experiência Match','#/match','green')}</section>`;}
function media(){return `<section class="panel"><div class="section-heading"><h2>Acervo demonstrativo</h2><span class="status neutral">Referências fornecidas pelo usuário</span></div><div class="media-library">${['living','dining','bedroom','living2','kitchen','balcony','facade','cinematic'].map((k,i)=>`<button data-gallery="${k}">${photo(k)}<span>Fotografia ilustrativa ${String(i+1).padStart(2,'0')}${icon('area')}</span></button>`).join('')}</div><p class="micro">Áreas fotográficas exibidas das referências de direção de arte. Sem upload de arquivos ou geração de anúncios.</p></section>`;}
function reports(){return `<section class="panel"><div class="section-heading"><h2>Visão do portfólio</h2><button class="btn outline" data-action="export-report">${icon('download')}Exportar CSV</button></div><div class="report-bars">${neighborhoods.map(n=>`<div><b>${n}</b><span><i style="width:70%"></i></span><strong>1 imóvel</strong></div>`).join('')}</div></section><section class="panel chart-panel"><h2>Interesse ao longo da semana</h2>${chart()}<p class="micro">Gráfico ilustrativo. O CSV exporta apenas os sete registros fictícios do catálogo.</p></section>`;}
function settings(){return `<section class="panel settings-panel"><h2>Preferências da demonstração</h2><p>Este protótipo não utiliza contas ou autenticação. Favoritos, matches e visitas ficam somente neste navegador.</p><div class="setting-row"><div><b>Dados da sessão</b><p>Limpar favoritos, decisões do Match e agendamentos simulados.</p></div><button class="btn outline" data-action="clear-data">Limpar dados</button></div><div class="setting-row"><div><b>Identidade visual</b><p>Conheça os componentes e tokens da interface.</p></div>${button('Ver design system','#/design-system','outline')}</div><div class="setting-row"><div><b>Movimento reduzido</b><p>A interface respeita automaticamente a preferência do seu sistema operacional.</p></div>${icon('check')}</div></section>`;}
